/* =====================================================================
   PART 14 · PRACTICE ARENA (engine + beginner & intermediate challenges)
   #/page/practice            → challenge list (filter by level / search)
   #/page/practice/<id>       → prompt → your notes → hint 1 → 2 → 3 →
                                 solution outline with an animated diagram
   Also defines SDA.miniDiagram: a compact grid layout used by practice
   solutions and project HLDs (nodes placed by column/row).
   ===================================================================== */
(function(){
const SDA = window.SDA; const {el, esc} = SDA.u; const ui = SDA.ui; const h = SDA.h; const Store = SDA.store;
const frag = html => document.createRange().createContextualFragment(html);

/* ---------- mini diagram DSL ----------
   n: [[id, type, label, sub, col, row, w?]]   col 0..4, row 0..2
   e: 'a>b c>d a>c~0.3'                         (~ = curve)
   f: [[note, 'a>b:label|b>c']]                 (animated steps)       */
const COLX = c => 70 + c * 185, ROWY = r => 50 + r * 115;
function miniSpec(spec){
  const nodes = spec.n.map(([id, type, label, sub, c, r, w]) => ({id, type, label, sub:sub || '', x:COLX(c), y:ROWY(r), w:w || (type === 'client' ? 110 : 134)}));
  const edges = spec.e.trim().split(/\s+/).map(s => { const [ab, cv] = s.split('~'); const [from, to] = ab.split('>'); return cv ? {from, to, curve:+cv} : {from, to}; });
  const steps = (spec.f || []).map(([note, hops]) => ({note, flow:hops.split('|').map(x => { const i = x.indexOf(':'); const ab = i >= 0 ? x.slice(0, i) : x, lab = i >= 0 ? x.slice(i + 1).trim() : null; const [a, b] = ab.split('>').map(s => s.trim()); return lab ? [a, b, lab] : [a, b]; })}));
  const W = Math.max(...nodes.map(n => n.x + n.w / 2)) + 16, H = Math.max(...nodes.map(n => n.y)) + 50;
  return {nodes, edges, steps, w:Math.max(560, W), h:Math.max(200, H)};
}
SDA.miniSpec = miniSpec;
SDA.miniDiagram = function(host, spec, title){ const s = miniSpec(spec); return new SDA.Diagram(host, {title, w:s.w, h:s.h, minW:560, alt:title, nodes:s.nodes, edges:s.edges, steps:s.steps, autoplay:false}); };

/* ---------- challenge registry ---------- */
SDA.challenges = SDA.challenges || new Map();
const LV = {beginner:{label:'Beginner', icon:'🌱'}, intermediate:{label:'Intermediate', icon:'🧱'}, advanced:{label:'Advanced', icon:'🚀'}};
SDA.addKind('challenge', c => { ['id', 'level', 'title', 'prompt', 'hints', 'solution'].forEach(k => { if (c[k] == null) throw new Error('challenge ' + (c.id || '?') + ' needs ' + k); }); if (c.hints.length !== 3) throw new Error('challenge ' + c.id + ' needs 3 hints'); SDA.challenges.set(c.id, c); });
SDA.searchProviders.push(() => [...SDA.challenges.values()].map(c => ({kind:'Practice', icon:c.icon || '🧩', title:c.title, sub:'Practice · ' + LV[c.level].label, href:'#/page/practice/' + c.id, kw:(c.tags || []).join(' ')})));
SDA.statProviders.push({label:'Practice challenges', count:() => SDA.challenges.size});
const notesKey = id => 'sda:practice-notes:' + id;
const getNotes = id => { try { return localStorage.getItem(notesKey(id)) || ''; } catch(e){ return ''; } };
const setNotes = (id, v) => { try { localStorage.setItem(notesKey(id), v); } catch(e){} };
const crumbs = list => el('nav', {class:'crumbs', 'aria-label':'Breadcrumb', html:list.map(([href, t]) => href ? `<a href="${href}">${esc(t)}</a>` : `<span aria-current="page">${esc(t)}</span>`).join('<span aria-hidden="true">/</span>')});

function renderList(ctx){
  const c = ctx.content; ctx.wide = true; let level = 'all', q = '', status = 'all';
  c.append(crumbs([['#/', 'Home'], [null, 'Practice Arena']]), el('h1', {class:'page-title'}, '🧩 Practice Arena'),
    el('p', {class:'lead'}, 'Design problems to solve on your own first. Write your approach, take hints one at a time, then compare with a full solution outline and diagram. Your notes stay in this browser.'));
  const all = [...SDA.challenges.values()];
  const solved = () => all.filter(x => Store.isDone('practice:' + x.id)).length;
  const prog = el('p', {class:'lab-hint'});
  const grid = el('div');
  const levelSel = ui.select({label:'Level', value:'all', options:[['all', 'All levels'], ['beginner', '🌱 Beginner'], ['intermediate', '🧱 Intermediate'], ['advanced', '🚀 Advanced']], onChange:v => { level = v; draw(); }});
  const statusSel = ui.select({label:'Status', value:'all', options:[['all', 'All'], ['todo', 'Not solved yet'], ['done', 'Solved']], onChange:v => { status = v; draw(); }});
  const search = el('input', {class:'input', type:'search', placeholder:'Filter by keyword…', 'aria-label':'Filter challenges'}); search.addEventListener('input', () => { q = search.value.toLowerCase(); draw(); });
  c.append(el('div', {class:'ctl-grid', style:{margin:'10px 0'}}, levelSel.el, statusSel.el, el('label', {class:'field'}, el('span', null, 'Search'), search)), prog, grid);
  function draw(){
    prog.textContent = `${solved()} of ${all.length} solved.`; grid.innerHTML = '';
    Object.keys(LV).forEach(lv => {
      if (level !== 'all' && level !== lv) return;
      const list = all.filter(x => x.level === lv && (!q || (x.title + ' ' + (x.tags || []).join(' ') + ' ' + SDA.u.stripHtml(x.prompt)).toLowerCase().includes(q)) && (status === 'all' || (status === 'done') === Store.isDone('practice:' + x.id)));
      if (!list.length) return;
      grid.append(el('div', {class:'sect-h'}, el('div', null, el('h2', null, `${LV[lv].icon} ${LV[lv].label}`), el('p', null, `${list.length} challenge${list.length > 1 ? 's' : ''}`))));
      const g = el('div', {class:'grid c3'});
      list.forEach(x => { const done = Store.isDone('practice:' + x.id); g.append(el('a', {class:'card glow', href:'#/page/practice/' + x.id}, el('div', {class:'row', style:{justifyContent:'space-between'}}, el('span', {class:'ico-lg', 'aria-hidden':'true'}, x.icon || '🧩'), done ? el('span', {class:'chip', style:{color:'var(--ok)'}}, '✓ solved') : el('span', {class:'chip'}, `${x.minutes || 30} min`)), el('b', {style:{display:'block', marginTop:'8px', color:'var(--text)', fontSize:'16px'}}, x.title), el('p', {class:'muted', style:{margin:'6px 0 0', fontSize:'14px'}}, x.tagline || ''))); });
      grid.append(g);
    });
    if (!grid.children.length) grid.append(el('div', {class:'empty'}, 'No challenges match these filters.'));
  }
  draw();
}

function renderOne(ctx, x){
  const c = ctx.content; ctx.title = x.title; ctx.track = {kind:'Practice', title:x.title, icon:x.icon || '🧩'};
  const all = [...SDA.challenges.values()]; const i = all.indexOf(x);
  c.append(crumbs([['#/', 'Home'], ['#/page/practice', 'Practice Arena'], [null, x.title]]));
  const doneB = ui.button(Store.isDone('practice:' + x.id) ? '✓ Solved' : 'Mark as solved', () => { const v = !Store.isDone('practice:' + x.id); Store.setDone('practice:' + x.id, v); doneB.innerHTML = v ? '✓ Solved' : 'Mark as solved'; }, 'sm');
  c.append(el('div', {class:'row', style:{marginTop:'12px', flexWrap:'wrap'}}, el('span', {class:'chip lvl'}, `${LV[x.level].icon} ${LV[x.level].label}`), el('span', {class:'chip'}, `⏱ ${x.minutes || 30} min`), ...(x.tags || []).map(t => el('span', {class:'chip'}, t)), doneB));
  c.append(el('h1', {class:'page-title'}, `${x.icon || '🧩'} ${x.title}`));
  c.append(el('div', {class:'prose'}, frag(`<p>${x.prompt}</p>` + (x.constraints && x.constraints.length ? `<h4>Constraints and numbers</h4>${h.list(x.constraints)}` : ''))));
  // notes
  const ta = el('textarea', {class:'input', rows:'6', style:{width:'100%', fontFamily:'var(--font-mono)', fontSize:'13px'}, placeholder:'Your approach: requirements, estimates, APIs, data model, components, bottlenecks… (saved in this browser)', 'aria-label':'Your notes'}); ta.value = getNotes(x.id); ta.addEventListener('input', () => setNotes(x.id, ta.value));
  c.append(el('h3', {style:{margin:'22px 0 8px'}}, '✍️ Your design first'), ta);
  // hints → solution
  const hintBox = el('div'); let shown = 0; const solBox = el('div');
  const hintB = ui.button('💡 Show hint 1', () => { if (shown >= 3) return; hintBox.append(el('div', {class:'callout info', style:{margin:'8px 0'}, html:`<b>Hint ${shown + 1}.</b> ${x.hints[shown]}`})); shown++; if (shown < 3) hintB.innerHTML = `💡 Show hint ${shown + 1}`; else { hintB.disabled = true; hintB.innerHTML = 'All hints shown'; solB.disabled = false; } }, 'sm');
  const solB = ui.button('📐 Show the solution outline', () => { solB.disabled = true; renderSolution(solBox, x); }, 'sm primary'); solB.disabled = true;
  const skip = el('button', {type:'button', class:'btn sm ghost'}, 'Skip to solution');
  skip.addEventListener('click', () => { if (solBox.childNodes.length) return; while (shown < 3) hintB.click(); solB.click(); });
  c.append(el('h3', {style:{margin:'22px 0 8px'}}, '🪜 Hints (one at a time)'), el('div', {class:'pill-row'}, hintB, solB, skip), hintBox, solBox);
  // prev / next
  const prev = all[i - 1], next = all[i + 1];
  c.append(el('div', {class:'row', style:{justifyContent:'space-between', marginTop:'28px', flexWrap:'wrap', gap:'8px'}}, prev ? el('a', {class:'btn sm ghost', href:'#/page/practice/' + prev.id}, '← ' + prev.title) : el('span'), next ? el('a', {class:'btn sm', href:'#/page/practice/' + next.id}, next.title + ' →') : el('span')));
}
function renderSolution(box, x){
  const s = x.solution;
  box.append(el('h3', {style:{margin:'22px 0 8px'}}, '📐 Solution outline'));
  if (s.summary) box.append(el('div', {class:'prose'}, frag(`<p>${s.summary}</p>`)));
  if (s.diagram){ const d = el('div'); box.append(d); SDA.miniDiagram(d, s.diagram, x.title + ': reference design'); }
  const g = el('div', {class:'grid c2'});
  (s.points || []).forEach(([hd, body]) => g.append(el('div', {class:'card'}, el('b', null, hd), el('div', {class:'prose', style:{marginTop:'6px'}}, frag(body)))));
  box.append(g);
  if (s.tradeoffs && s.tradeoffs.length) box.append(el('div', {class:'prose'}, frag('<h4>Trade-offs to mention</h4>' + h.table(['Decision', 'Why', 'What you give up'], s.tradeoffs, []))));
  const refs = (x.refs || []).map(r => SDA.resolve(r)).filter(Boolean);
  if (refs.length) box.append(el('h4', {style:{margin:'18px 0 8px'}}, '📚 Go deeper'), el('div', {class:'pill-row'}, ...refs.map(r => el('a', {class:'chip', href:r.href}, `${r.icon || ''} ${r.title}`))));
}
SDA.register({kind:'page', id:'practice', icon:'🧩', title:'Practice Arena', summary:'Design challenges with hints and solution outlines',
  render(ctx){ const x = ctx.args[0] && SDA.challenges.get(ctx.args[0]); if (ctx.args[0] && !x){ ctx.content.append(el('div', {class:'empty'}, 'Challenge not found. ', el('a', {href:'#/page/practice'}, 'All challenges →'))); return; } x ? renderOne(ctx, x) : renderList(ctx); }});
SDA.register({kind:'nav', label:'Practice Arena', href:'#/page/practice', icon:'🧩', order:4, group:'explore', desc:'Design challenges with hints 1→2→3 and solutions', count:() => SDA.challenges.size});

/* =========================== BEGINNER =========================== */
const C = def => SDA.register(Object.assign({kind:'challenge'}, def));
C({id:'page-views', level:'beginner', icon:'👀', minutes:25, title:'Page-view counter for a blog', tagline:'Count every view without melting the database.', tags:['counters', 'batching', 'caching'],
  prompt:'A popular blog wants a badge on every post that says “👀 12,431 views”. When Asha opens a post, the badge should change to 12,432 within a few seconds. Most posts get a few views, but a viral post can get thousands of views every second. How would you count the views?',
  constraints:['10 million page views a day across all posts: 10M ÷ 86,400 s ≈ 115 views a second on average', 'One viral post can get 5,000 views a second', 'The number shown may be a few seconds late', 'Counts must never go down, and must survive a restart', 'A relational database already exists'],
  hints:['What happens if every view runs <code>UPDATE posts SET views = views + 1</code> on the same row? Think about 5,000 of them in one second.', 'You do not have to save every view to the database one at a time. Where could you add them up first?', 'Add the views in a fast in-memory store such as Redis, using its <code>INCR</code> command. Every few seconds, save the new total to the database. Show the badge from the cache.'],
  solution:{summary:'Separate counting from storing. Each view adds 1 to a fast counter in Redis. Every few seconds a flusher adds the new views to the database, and the badge reads the cached number.',
    diagram:{n:[['u', 'client', 'Reader', '', 0, 1], ['app', 'service', 'Blog server', '', 1, 1], ['redis', 'cache', 'Redis', 'INCR views:{post}', 2, 0], ['flush', 'service', 'Flusher', 'every 5 s', 3, 0], ['db', 'db', 'Posts DB', 'views column', 3, 2]], e:'u>app app>redis redis>flush flush>db app>db', f:[['A view adds 1 to a counter in Redis. This is one tiny, atomic step.', 'u>app:GET /post/42|app>redis:INCR'], ['Every few seconds the flusher takes the new views and adds them to the database in one write.', 'redis>flush:take new views|flush>db:views += 3,812']]},
    points:[['1 · Requirements', '<p>The number can be a little late. Totals must be saved safely. Some posts get far more views than others.</p>'], ['2 · Estimate', '<p>10M ÷ 86,400 ≈ 115 views a second on average. That is easy. The real problem is one viral post at 5,000 a second, because all those updates fight over one database row.</p>'], ['3 · Data', '<p>The database keeps <code>posts.views</code>, the saved total. Redis keeps a counter <code>views:{post}</code> for views not yet saved, and a list of posts that have new views.</p>'], ['4 · Deep dive', '<p>The flusher must read the new views and reset the counter in one step. Use the Redis command <code>GETDEL</code> or a small Lua script. If the database write fails, add the views back.</p><p>If Redis restarts, you lose at most a few seconds of views. That is fine here. Turn on Redis persistence (AOF) if it is not.</p>'], ['5 · Unique readers?', '<p>To count each reader once, use a HyperLogLog per post (Redis <code>PFADD</code>). It counts distinct readers with about 1% error and uses only 12 KB.</p>'], ['6 · Bottlenecks', '<p>One Redis key lives on one CPU core, which handles roughly 100,000 operations a second. A post above that would split its counter into N parts and add them up when read.</p>']],
    tradeoffs:[['Buffer views in Redis', 'No more fighting over one row', 'A crash can lose a few seconds of views'], ['Approximate unique counts (HyperLogLog)', 'Very little memory', 'About 1% error']]},
  refs:['l:hll-cms', 'l:cache-strategies', 'l:locking']});
C({id:'qr-menu', level:'beginner', icon:'📱', minutes:25, title:'QR-code menus for 50,000 restaurants', tagline:'Mostly static, sometimes edited, read at lunchtime by everyone.', tags:['cdn', 'cache invalidation', 'static'],
  prompt:'Restaurants print a QR code on each table. When Ravi scans it, the restaurant’s menu opens on his phone. Owners edit prices and mark dishes “sold out” from a dashboard. Design the system so menus load fast, even on a bad 4G connection.',
  constraints:['50,000 restaurants with about 200 dishes each, with photos', 'Lunch peak: 20,000 menu opens a second', 'A “sold out” change should show within a minute', 'A very small team, so keep it simple'],
  hints:['How often does a menu change, compared with how often it is read?', 'Could the menu be a ready-made file, instead of a database query on every scan?', 'Make the menu file when the owner edits it, and keep it in object storage behind a CDN. Clear or version that one file when the owner changes something.'],
  solution:{summary:'Menus are read far more than they are edited. So build each menu as a ready-made file whenever it is edited, and serve it from a CDN. The QR code points at one stable address.',
    diagram:{n:[['diner', 'client', 'Diner phone', '', 0, 0], ['owner', 'client', 'Owner', 'dashboard', 0, 2], ['cdn', 'cdn', 'CDN', 'menu files', 1, 0], ['api', 'service', 'Menu API', 'edits', 1, 2], ['db', 'db', 'Menus DB', '', 2, 2], ['build', 'service', 'Renderer', 'JSON + HTML', 3, 1], ['s3', 'db', 'Object storage', 'menu/{id}.json', 3, 0]], e:'diner>cdn cdn>s3 owner>api api>db api>build build>s3', f:[['A scan loads the menu file from the nearest CDN edge.', 'diner>cdn:GET /m/7781'], ['An edit updates the DB and re-renders that restaurant’s file, then invalidates the CDN path.', 'owner>api:dal makhani sold out|api>db|api>build|build>s3:new menu file']]},
    points:[['Estimate', '<p>20,000 opens a second × about 200 KB (with small photos) = 4 GB a second. Only a CDN can carry that. Edits are a few a second at most.</p>'], ['Data', '<p>Tables: <code>restaurants</code> and <code>dishes(id, restaurant_id, name, price, available, photo_key)</code>. Each menu file has a version number that goes up on every edit.</p>'], ['Freshness', '<p>Use a short CDN cache time (60 s), or clear that one path when the owner edits. Photos use file names built from their content, so they can be cached forever.</p>'], ['Failure', '<p>If the API is down, menus still load from the CDN. Only edits have to wait.</p>'], ['Extras', '<p>Ordering from the table is a different flow with many writes. Keep it apart from menu reads.</p>']],
    tradeoffs:[['Static files on a CDN', 'Fast, cheap, and still works when the backend is down', 'An edit takes a short time to show'], ['A short cache time or clearing the path', 'A short cache time is the simplest', 'Menus can be stale for up to that many seconds']]},
  refs:['l:cdn', 'l:cache-invalidation']});
C({id:'thumbnails', level:'beginner', icon:'🖼️', minutes:30, title:'Image thumbnail service', tagline:'Upload once, resize in the background, serve fast.', tags:['async jobs', 'object storage', 'cdn', 'queues'],
  prompt:'Sellers on a marketplace app upload product photos of up to 20 MB. The app needs 4 sizes (small thumbnail to full screen), in WebP and JPEG. The upload should finish quickly, and the smaller sizes should show up within a few seconds.',
  constraints:['2M uploads a day, with peaks of 200 a second', 'Resizing takes about 1 s of CPU for each image', 'Images are never edited, only deleted', 'The service must cope with duplicate uploads and broken files'],
  hints:['Should the upload request wait until the resizing is done?', 'Where should the original file go, and how does the app learn when the sizes are ready?', 'Upload straight to object storage with a pre-signed URL. Put a job on a queue and let a pool of workers resize. Serve all sizes through a CDN. Retry failed jobs, and send jobs that keep failing to a dead-letter queue.'],
  solution:{summary:'Separate the upload from the processing. The app uploads the original straight to object storage, and a queue message wakes workers that make the sizes. A CDN serves each size by a URL built from the image’s hash.',
    diagram:{n:[['app', 'client', 'Seller app', '', 0, 1], ['api', 'service', 'Upload API', 'pre-signed URLs', 1, 1], ['s3', 'db', 'Object storage', 'originals + sizes', 2, 0], ['q', 'queue', 'Resize jobs', '+ DLQ', 2, 2], ['w', 'service', 'Workers', 'autoscaled', 3, 2], ['db', 'db', 'Images DB', 'status', 3, 1], ['cdn', 'cdn', 'CDN', '', 3, 0]], e:'app>api app>s3~-0.25 api>q q>w w>s3 w>db cdn>s3 api>db', f:[['The app gets a pre-signed URL and uploads directly to storage. The API never touches the bytes.', 'app>api:POST /uploads|app>s3:PUT original'], ['A job is queued. A worker resizes, writes four sizes, then marks the image ready.', 'api>q:resize 9f2c|q>w|w>s3:4 sizes|w>db:READY'], ['Buyers load sizes from the CDN.', 'cdn>s3:miss → size']]},
    points:[['Estimate', '<p>200 uploads a second × 1 s of CPU = 200 cores at peak. The average is 2M ÷ 86,400 s ≈ 23 a second, or about 25 cores. Add workers when the queue grows.</p>'], ['Safe to repeat', '<p>Name the outputs by the SHA-256 hash of the original. A duplicate upload or a retried job then overwrites the same files.</p>'], ['Failures', '<p>Retry with a growing wait. After N failures, move the job to a dead-letter queue and mark the image FAILED (a broken file).</p>'], ['Serving', '<p>A URL such as <code>/img/{hash}/w640.webp</code> never changes, so it can be cached forever. The server picks WebP or JPEG for each browser.</p>'], ['Security', '<p>Check the file type and size, remove the GPS location from the photo, and scan for malware before it goes live.</p>']],
    tradeoffs:[['A pre-signed direct upload', 'The API servers stay light', 'The file must be checked after it is uploaded'], ['Make all 4 sizes at once', 'The first view is fast', 'Storage is used for sizes nobody views, unlike resizing on demand']]},
  refs:['l:queues-pubsub-streams', 'l:ordering-dlq', 'l:transcoding-pipeline']});
C({id:'quiz-leaderboard', level:'beginner', icon:'🏆', minutes:25, title:'Live leaderboard for a quiz app', tagline:'Top 100 and “your rank” for a million players.', tags:['redis', 'sorted sets', 'ranking'],
  prompt:'A quiz app runs a live contest for 20 minutes every evening, with up to 1 million players. After each question, every player sees the top 100 and their own rank. For example, Meera sees “You are #48,213”. Design the leaderboard.',
  constraints:['1M players, with scores updated after each of 20 questions', 'After each question about 1M players ask for their rank, within a few seconds', 'On equal scores, the player who answered earlier ranks higher', 'The final results must be saved forever'],
  hints:['Sorting 1M rows in SQL after every question is too slow. Which data structure keeps items in order while they change?', 'A Redis sorted set updates and finds a rank in O(log n) time. How do you break ties by time?', 'Store one number that holds the score and the answer time, for example score × 10⁹ minus the milliseconds taken. Use ZADD or ZINCRBY to update and ZREVRANK for the rank. Cache the top 100 for a second, and save the results at the end.'],
  solution:{summary:'Keep the live board in a Redis sorted set for each contest, because updates and rank lookups take O(log n) time. Put the tie-break inside the score. Serve the top 100 from a 1-second cache, and write the final results to the database when the contest ends.',
    diagram:{n:[['p', 'client', 'Player', '', 0, 1], ['api', 'service', 'Quiz API', '', 1, 1], ['z', 'cache', 'Redis ZSET', 'board:{contest}', 2, 0], ['top', 'cache', 'Top-100 cache', '1 s', 2, 2], ['db', 'db', 'Results DB', 'after contest', 3, 1]], e:'p>api api>z api>top top>z api>db', f:[['An answer updates the player’s score in the sorted set.', 'p>api:answer Q7|api>z:ZADD composite score'], ['Players read their rank and the cached top 100.', 'api>z:ZREVRANK|api>top:top 100'], ['At the end, the final board is written permanently.', 'api>db:bulk insert results']]},
    points:[['Estimate', '<p>1M updates for a question, spread over about 10 s, is 100,000 operations a second. One Redis node can do this. If many contests run at once, give each contest its own node.</p>'], ['Ties', '<p>Use <code>composite = points × 10⁹ + (10⁹ − ms_taken)</code>. Players with equal points then sort by speed.</p>'], ['Reads', '<p>The top 100 is the same for everyone, so work it out once a second (<code>ZREVRANGE 0 99</code>) and cache it. “My rank” is one <code>ZREVRANK</code> for each user.</p>'], ['Durability', '<p>Redis holds the live board. Every answer is also written to a log, so the board can be rebuilt if Redis fails.</p>']],
    tradeoffs:[['A Redis sorted set', 'Rank and update take O(log n) time', 'It is in memory, so it must be saved separately'], ['A cached top 100', 'A huge cut in reads', 'It can be up to 1 s old']]},
  refs:['l:redis-vs-memcached', 'l:cache-strategies']});
C({id:'otp-login', level:'beginner', icon:'🔐', minutes:25, title:'OTP login service', tagline:'Six digits, five minutes, and no SMS bombing.', tags:['security', 'ttl', 'rate limiting', 'failover'],
  prompt:'Priya logs in to an app with a 6-digit code sent by SMS. Design the OTP service: making the code, sending it, checking it, and stopping abuse.',
  constraints:['50 logins a second at peak, and 300 a second during sales', 'An OTP is valid for 5 minutes, with at most 5 attempts', 'SMS providers sometimes fail or slow down', 'Attackers try SMS bombing and brute force'],
  hints:['Where would you store the OTP so it expires on its own, and in what form?', 'What stops someone from sending 1,000 SMS to one number, or from guessing all 1,000,000 codes?', 'Store a hash of the OTP with a 5-minute TTL and an attempts counter. Limit sends for each phone and each IP address. Send through a queue with a backup provider, and compare codes in constant time.'],
  solution:{summary:'Make a random code and store only its hash, with a TTL and an attempt counter. Send it through a queue that can switch between SMS providers, and limit both sending and checking.',
    diagram:{n:[['u', 'client', 'User app', '', 0, 1], ['api', 'service', 'Auth API', '', 1, 1], ['redis', 'cache', 'Redis', 'otp hash · TTL 300 s', 2, 0], ['rl', 'cache', 'Rate limits', 'per phone / IP', 2, 2], ['q', 'queue', 'SMS queue', '', 3, 1], ['sms', 'ext', 'SMS providers', 'primary + backup', 4, 1]], e:'u>api api>redis api>rl api>q q>sms', f:[['Request a code: check send limits, store the hash with a TTL, queue the SMS.', 'u>api:POST /otp|api>rl:3 per 10 min|api>redis:SET hash EX 300|api>q|q>sms'], ['Verify: compare hashes, count attempts, delete on success.', 'u>api:POST /verify 482913|api>redis:check + INCR attempts']]},
    points:[['Making the code', '<p>Use a cryptographic random number generator. Store <code>sha256(code + a salt for this request)</code>, never the code itself.</p>'], ['Limits', '<p>For sends, allow for example 3 in 10 minutes for each phone and each device, plus a limit for each IP address. For checks, allow 5 attempts, then cancel the code.</p>'], ['Delivery', '<p>Use a queue with a timeout of 2 to 3 s for each provider, and switch to a backup provider on failure. Track delivery receipts for each provider, so you can route around a failing one.</p>'], ['Delay for the user', '<p>Total time is the queue wait plus the provider time. Show “resend in 30 s”, so users do not retry in a hurry.</p>'], ['Security', '<p>Compare in constant time. Tie the OTP to the login attempt (a request id), so it cannot be replayed elsewhere.</p>']],
    tradeoffs:[['SMS OTP', 'Works for everyone with a phone', 'SIM-swap and phishing risk, compared with app-based codes or passkeys'], ['Strict rate limits', 'Stops bombing and brute force', 'Some friction for real users']]},
  refs:['l:rate-limiting', 'l:password-hashing', 'l:timeouts-retries', 'case:notification-service']});
C({id:'uptime-monitor', level:'beginner', icon:'🟢', minutes:30, title:'Uptime monitor and status page', tagline:'Check 100K URLs every minute and alert when they go down.', tags:['scheduling', 'workers', 'alerting'],
  prompt:'Build a service like a simple uptime checker. Customers add web addresses, and the system checks each one every minute from several regions. It alerts on failures and shows a public status page. For example, when api.shop.in stops answering, its owner gets an email within 2 minutes.',
  constraints:['100,000 monitored URLs, checked every minute from 3 regions', 'A site is “down” only if 2 of the 3 regions agree', 'Alerts by email and webhook within 2 minutes', 'Status pages get traffic spikes during outages'],
  hints:['How many checks a second is that, and how do you spread them out, instead of sending them all at :00?', 'How do you avoid waking a customer because one region had a short network problem?', 'Split the URLs across worker machines by hash, and give each URL its own start second. Save results in a time-series store. Check a “2 of 3 regions” rule for each URL, and serve status pages as static files from a CDN.'],
  solution:{summary:'Split the URLs across checker workers in each region, with start times spread out. Collect the results in one place, and let an evaluator apply a quorum rule and a short debounce before it alerts. Status pages are cached at the edge.',
    diagram:{n:[['cust', 'client', 'Customer', '', 0, 1], ['api', 'service', 'Config API', '', 1, 1], ['db', 'db', 'Monitors DB', '', 1, 2], ['chk', 'service', 'Checkers ×3 regions', 'sharded by hash', 2, 0], ['ts', 'db', 'Results', 'time series', 3, 0], ['eval', 'service', 'Evaluator', '2-of-3 rule', 3, 1], ['notif', 'ext', 'Email / webhooks', '', 4, 1], ['cdn', 'cdn', 'Status pages', 'CDN', 2, 2]], e:'cust>api api>db chk>db chk>ts ts>eval eval>notif eval>cdn', f:[['Checkers in three regions probe their share of URLs each minute and record results.', 'chk>db:my shard|chk>ts:latency, status'], ['The evaluator sees 2 of 3 regions failing for 2 checks in a row and alerts.', 'ts>eval|eval>notif:DOWN api.example.com'], ['The status page is regenerated and served from the CDN.', 'eval>cdn:incident page']]},
    points:[['Estimate', '<p>100,000 URLs × 3 regions ÷ 60 s = 5,000 checks a second. With about 2 s for each check, that is about 10,000 requests in flight. Use workers with async I/O, a few hundred in each region.</p>'], ['Scheduling', '<p>Give each URL a start offset of hash(id) mod 60 s, so the load is flat. Workers own shards by consistent hashing, and the shards move to others when a worker dies.</p>'], ['False alarms', '<p>Ask for 2 of 3 regions and 2 failed checks in a row. Also alert on recovery, with a short cool-down.</p>'], ['Storage', '<p>Keep the raw results for 7 days, and roll them up into uptime for each hour for months.</p>']],
    tradeoffs:[['A quorum across regions', 'Few false alarms', 'Detection is slightly slower'], ['Static status pages', 'They survive the traffic spikes during an outage', 'They update every 30 s or so, not instantly']]},
  refs:['l:alerting-oncall', 'l:time-series', 'l:consistent-hashing']});
C({id:'static-hosting', level:'beginner', icon:'🌐', minutes:25, title:'Static website hosting', tagline:'Deploy with git push, and serve millions from the edge.', tags:['cdn', 'deployments', 'immutable assets'],
  prompt:'Design a simple static-site host. Asha pushes a folder of HTML, CSS and JS, and her site is served on her own domain with HTTPS, anywhere in the world. A deploy must switch all at once, and she must be able to go back to the last version in one click.',
  constraints:['1M sites, most of them tiny, and a few with millions of visits', 'A deploy must never serve a mix of old and new files', 'Instant rollback to any earlier deploy', 'Free TLS certificates for custom domains'],
  hints:['If you overwrite files in place, what does a visitor see halfway through a deploy?', 'What if every deploy got its own folder that never changes, and the domain pointed at one of them?', 'Upload each deploy to a new folder named by its content. Then switch one pointer (domain to deploy id) in a key-value store that the edges read. A rollback is just switching the pointer back.'],
  solution:{summary:'Every deploy never changes after it is uploaded and is stored under its own id. The live site is a pointer from the hostname to a deploy id. The edges read the pointer (cached briefly) and serve the files from storage, with long cache times for files that have a hash in their name.',
    diagram:{n:[['dev', 'client', 'Developer', 'git push', 0, 0], ['v', 'client', 'Visitor', '', 0, 2], ['build', 'service', 'Deploy API', 'uploads files', 1, 0], ['s3', 'db', 'Object storage', 'deploys/{id}/…', 2, 0], ['kv', 'cache', 'Routing KV', 'host → deploy', 2, 1], ['edge', 'cdn', 'Edge servers', 'TLS + cache', 1, 2], ['acme', 'ext', 'Let’s Encrypt', 'certificates', 3, 2]], e:'dev>build build>s3 build>kv v>edge edge>kv edge>s3~-0.1 edge>acme~0.1', f:[['A deploy uploads every file to a new folder that never changes, then flips the pointer.', 'dev>build:push|build>s3:deploys/d812/|build>kv:site → d812'], ['A visitor’s request resolves the hostname and serves files from that deploy.', 'v>edge:GET /|edge>kv:site → d812|edge>s3:index.html']]},
    points:[['Switching all at once', '<p>A reader sees either the old pointer or the new one, never a mix of files.</p>'], ['Caching', '<p>Files with a hash in the name (<code>app.3f9c.js</code>) are cached forever. HTML is cached for a short time, or cleared at each deploy.</p>'], ['Domains and TLS', '<p>Check that the owner controls the domain. Then get a certificate with ACME, and store it so the edges can load it by SNI.</p>'], ['Dedupe', '<p>Store files by the hash of their content. A file that did not change is not uploaded twice.</p>']],
    tradeoffs:[['Deploys that never change, plus a pointer', 'One switch and an instant rollback', 'Storage for old deploys, so clear out the old ones'], ['A pointer cache at the edge', 'Fast lookups', 'A few seconds before a new deploy shows everywhere']]},
  refs:['l:cdn', 'l:deploy-strategies', 'l:https-tls']});
C({id:'news-comments', level:'beginner', icon:'💬', minutes:30, title:'Comments for a news site', tagline:'Threads, pagination, moderation, and an election-night spike.', tags:['pagination', 'moderation', 'caching', 'queues'],
  prompt:'A news site adds comments under every article, with replies, likes, “newest” and “top” sorting, and moderation for abuse. On a big news day, one article can get 50,000 comments. When Kabir opens that article, the first 20 comments should show at once.',
  constraints:['5M comments a day, with peaks of 500 writes a second on one article', 'Reads are 50 times the writes', 'Abusive comments should be hidden within seconds', 'A page loads the first 20 comments, and more as you scroll'],
  hints:['How would you page through 50,000 comments without <code>OFFSET 49980</code>?', 'Should moderation happen before a comment shows, or after? Should it make the writer wait?', 'Page with a cursor on (article_id, created_at, id). Cache the first page of each article for a few seconds. Send each new comment to a moderation queue: a fast automatic filter first, and a person checking later.'],
  solution:{summary:'Store comments by article, page through them with a cursor, and cache the busy first page. Moderate in two steps: a quick automatic check before a comment shows, and a later review that can hide it.',
    diagram:{n:[['r', 'client', 'Reader', '', 0, 1], ['api', 'service', 'Comments API', '', 1, 1], ['cache', 'cache', 'First-page cache', '5 s', 2, 0], ['db', 'db', 'Comments DB', 'by article', 2, 2], ['q', 'queue', 'Moderation queue', '', 3, 1], ['mod', 'service', 'Moderation', 'ML + humans', 4, 1]], e:'r>api api>cache api>db api>q q>mod mod>db~-0.3', f:[['A new comment passes a quick filter, then it is stored and queued for review.', 'r>api:POST comment|api>db:INSERT|api>q:review'], ['Readers get the cached first page. Scrolling uses a cursor.', 'r>api:GET ?cursor=…|api>cache:page 1|api>db:WHERE (created_at, id) < cursor']]},
    points:[['Data', '<p><code>comments(id, article_id, parent_id, author_id, body, status, created_at, likes)</code>, with an index on (article_id, created_at DESC, id).</p>'], ['Threads', '<p>Store <code>parent_id</code>. Load the top-level comments by cursor and the first few replies for each. “Load more replies” fetches by parent.</p>'], ['Top sorting', '<p>Work out a score now and then (likes with a decay over time). Do not sort 50,000 rows on every request.</p>'], ['Spikes', '<p>500 writes a second on one article is fine for a database. The first-page cache absorbs the reads.</p>']],
    tradeoffs:[['Show first, review later', 'Comments appear at once', 'Abuse is visible for a few seconds'], ['Cursor paging', 'A deep page costs the same as the first', 'You cannot jump to page 500']]},
  refs:['l:indexes', 'l:queues-pubsub-streams', 'l:api-design']});
C({id:'weather-cache', level:'beginner', icon:'⛅', minutes:20, title:'Caching a rate-limited weather API', tagline:'Your provider allows 1,000 calls a day, and your users want weather now.', tags:['caching', 'stale-while-revalidate', 'rate limits'],
  prompt:'Your app shows the current weather for the user’s city. The paid weather provider allows only 1,000 requests a day, and each answer takes 800 ms. You have 2 million users a day across 300 cities. When Neha opens the app in Pune, she should see the temperature at once.',
  constraints:['1,000 provider calls a day, a hard limit', '300 cities, and the weather can be up to 15 minutes old', 'The provider sometimes fails for an hour', 'Users should never wait 800 ms'],
  hints:['How many different things do you really need to fetch, and how often?', '300 cities every 15 minutes is how many calls a day? Does that fit in 1,000?', 'Cache the weather for each city, and refresh it in the background. Spend the daily budget on the busiest cities. The top 100 every 30 minutes would need 4,800 calls, which is too many, so choose carefully or use a bulk call. If the provider is down, show the old data.'],
  solution:{summary:'The key is the call budget. Cache the weather by city, not by user. Refresh it in the background on a schedule that fits the budget, and always answer from the cache, even if the data is old during an outage.',
    diagram:{n:[['u', 'client', 'App', '', 0, 1], ['api', 'service', 'Weather API', 'ours', 1, 1], ['cache', 'cache', 'Cache', 'city → weather', 2, 1], ['sched', 'service', 'Refresher', 'budgeted', 3, 0], ['prov', 'ext', 'Provider', '1,000/day', 4, 1]], e:'u>api api>cache sched>cache sched>prov', f:[['Users always read from the cache, never the provider.', 'u>api:GET /weather?city=Pune|api>cache'], ['A refresher spends the daily budget on the cities that matter most.', 'sched>prov:bulk: 20 cities|sched>cache:update']]},
    points:[['Budget math', '<p>1,000 calls ÷ 24 h ≈ 42 an hour. 300 cities every 15 minutes would need 300 × 4 × 24 = 28,800 calls a day.</p><p>So choose. Refresh the top 40 cities every hour (40 × 24 = 960 calls). Refresh the others only when someone asks and the data is older than 3 hours, or use a bulk call if there is one.</p>'], ['Stale while revalidate', '<p>Return the cached value at once. If it is old, start a refresh in the background, once for each city.</p>'], ['Outages', '<p>Keep the last known data and show “updated 2 h ago” instead of failing.</p>'], ['A cost alternative', '<p>Compare the price of a bigger plan with the cost of the engineering work. Sometimes buying more quota is the right design.</p>']],
    tradeoffs:[['A cache for each city', 'Fits the budget', 'No street-level detail'], ['Serve old data', 'Always fast and available', 'The data is old during outages']]},
  refs:['l:cache-strategies', 'l:cache-failure-modes', 'l:rate-limiting']});
C({id:'feature-flags', level:'beginner', icon:'🚩', minutes:30, title:'Feature-flag service', tagline:'Turn features on for 5% of users without a deploy.', tags:['configuration', 'push', 'local evaluation'],
  prompt:'Engineers want to turn features on and off while the app runs. They want to roll a feature out to 5% of users first, and to kill a bad feature in seconds. 300 services, each handling thousands of requests a second, must check these flags.',
  constraints:['300 services, with 50,000 flag checks a second in each service', 'A kill switch must work within 10 seconds', 'A flag check must add no network delay', 'A rollout to a percentage of users must be sticky for each user'],
  hints:['Can each flag check be a network call to the flag service? Multiply it out.', 'What if each service kept all the flag rules in memory and checked them on its own?', 'The SDK downloads all the rules and listens for changes (a stream, or polling every 5 s). It checks flags locally and puts each user in a bucket with hash(flag, user_id) mod 100, so a percentage stays sticky.'],
  solution:{summary:'Flags are checked inside each process, from a local copy of the rules. The flag service only sends out rule changes. A sticky rollout uses a hash of the flag and the user, so the same user always gets the same answer.',
    diagram:{n:[['eng', 'client', 'Engineer', 'dashboard', 0, 1], ['api', 'service', 'Flag API', '', 1, 1], ['db', 'db', 'Flags DB', 'rules + audit', 1, 2], ['stream', 'queue', 'Change stream', 'SSE / pub-sub', 2, 1], ['svc', 'service', 'Service + SDK', 'local rules', 3, 1], ['cdn', 'cdn', 'Rules snapshot', 'CDN', 2, 0]], e:'eng>api api>db api>stream stream>svc api>cdn svc>cdn', f:[['An engineer changes a rule. It is saved with an audit entry and sent out.', 'eng>api:checkout-v2 → 5%|api>db|api>stream'], ['SDKs apply the change in memory. Every check is a local function call.', 'stream>svc:rule update']]},
    points:[['Estimate', '<p>300 × 50,000 = 15M checks a second. That is impossible over the network and easy in memory.</p>'], ['Stickiness', '<p>bucket = hash(flag_key + user_id) mod 100. The flag is on if bucket &lt; percentage. Raising 5% to 10% keeps the first 5% of users on.</p>'], ['Resilience', '<p>The SDK starts from a saved copy of the rules (on a CDN or disk) if the flag service is down. A default value is coded for each flag.</p>'], ['Governance', '<p>Keep an audit log, an owner and an expiry date for each flag, and raise an alert on stale flags.</p>']],
    tradeoffs:[['Local checks', 'No delay, and it works even if the service is down', 'The rules (and the user attributes) must be available in each service'], ['Streaming updates', 'A kill switch works in seconds', 'Long-lived connections to manage']]},
  refs:['l:config-feature-flags', 'l:deploy-strategies']});

/* =========================== INTERMEDIATE =========================== */
C({id:'live-score', level:'intermediate', icon:'🏏', minutes:40, title:'Live cricket scores for 10 million fans', tagline:'One update every few seconds, to everyone at once.', tags:['fan-out', 'sse', 'cdn', 'pub/sub'],
  prompt:'A sports app shows live ball-by-ball cricket scores. During an India vs Pakistan match, 10 million fans have the score screen open. Every ball makes an update, and fans expect to see it within 2 to 3 seconds. How would you serve them all?',
  constraints:['10M viewers at once on one match, with about 1 update every 30 s plus commentary', 'Updates within 3 s', 'Clients on unreliable mobile networks', 'Cost matters, so avoid work for each user where you can'],
  hints:['Is the data different for each user? What does that mean for caching?', 'Compare 10M open WebSockets with 10M clients that fetch a cached file every 3 s.', 'Publish each update as a tiny JSON file on a CDN with a cache time of 1 to 2 s. Let clients fetch it again and again, or use SSE through a fan-out tier. The origin writes only once for each ball.'],
  solution:{summary:'Everyone sees the same score, so this is a broadcast problem, not a problem for each user. Write each update once to an origin, and let a CDN absorb the reads, with short-cache fetching or streams pushed from the edge.',
    diagram:{n:[['fan', 'client', 'Fans ×10M', '', 0, 1], ['cdn', 'cdn', 'CDN edges', 'score.json · TTL 2 s', 1, 1], ['origin', 'service', 'Score origin', '', 2, 1], ['scorer', 'client', 'Official scorer', '', 4, 1], ['ingest', 'service', 'Ingest API', 'validates', 3, 1], ['db', 'db', 'Match DB', 'ball log', 3, 2]], e:'fan>cdn cdn>origin scorer>ingest ingest>db ingest>origin', f:[['The scorer records a ball. It is logged, and a new score file is published.', 'scorer>ingest:4 runs|ingest>db|ingest>origin:score.json v812'], ['Clients poll the edge every 2 to 3 s. Edges fetch from the origin at most once for each cache time.', 'fan>cdn:GET score.json|cdn>origin:once per 2 s']]},
    points:[['Estimate', '<p>Fetching every 3 s: 10M ÷ 3 ≈ 3.3M requests a second at the edge. A response of 1 KB makes about 27 Gbps, which is fine for a CDN. The origin sees about 1 request from each edge for each cache time.</p>'], ['A push alternative', '<p>SSE or WebSockets cut the delay and the requests. But 10M connections need a large fan-out tier. Many apps fetch scores and use push only for notifications.</p>'], ['Order', '<p>Each update has a version number. Clients ignore an older version that arrives late.</p>'], ['Notifications', '<p>Wickets and milestones go out as push notifications through topic subscriptions, with a rate limit.</p>']],
    tradeoffs:[['Fetching often, with a short CDN cache', 'Simple, cheap and robust', 'A few seconds of delay, and a steady volume of requests'], ['Push (SSE)', 'Lower delay and fewer requests', 'Millions of open connections']]},
  refs:['l:cdn', 'l:realtime-transports', 'case:hotstar']});
C({id:'job-scheduler', level:'intermediate', icon:'⏰', minutes:45, title:'Distributed job scheduler (cron at scale)', tagline:'Run 10 million scheduled jobs, each exactly when due, even when machines die.', tags:['scheduling', 'leases', 'exactly-once', 'queues'],
  prompt:'Design a service where teams register jobs such as “every day at 02:00 IST”, “in 30 minutes” or “every 5 minutes”. Each job calls a web address or puts a message on a queue. Jobs must run on time, and never twice.',
  constraints:['10M registered jobs, with up to 50,000 due in the same second (for example at midnight)', 'Fire within a few seconds of the due time', 'No job is lost if a scheduler node dies', 'Jobs may take minutes, with retries and a growing wait after a failure'],
  hints:['How do you find the jobs that are due right now, without scanning 10M rows every second?', 'If two scheduler nodes both see a due job, how do you make sure only one runs it?', 'Index jobs by next_run_at and split them across scheduler nodes. Claim a due job with a conditional update (or SELECT … FOR UPDATE SKIP LOCKED) and a lease. Push it to a queue for workers, then work out and save the next run time.'],
  solution:{summary:'Store jobs with their next due time in a split table. Each scheduler node checks its own part for due jobs and claims each one with a lease, so only one node fires it. It hands the job to a worker queue and sets the next time, and workers make the run safe to repeat.',
    diagram:{n:[['team', 'client', 'Team', 'registers job', 0, 1], ['api', 'service', 'Jobs API', '', 1, 1], ['db', 'db', 'Jobs DB', 'next_run_at index', 2, 1], ['sch', 'service', 'Schedulers', 'own partitions', 2, 0], ['q', 'queue', 'Run queue', '', 3, 0], ['w', 'service', 'Workers', 'retries', 4, 0], ['target', 'ext', 'Target endpoint', '', 4, 2]], e:'team>api api>db sch>db sch>q q>w w>target w>db', f:[['A team registers a job. Its next_run_at is worked out and stored.', 'team>api:every day 02:00 IST|api>db'], ['Each scheduler claims due jobs in its partitions with a lease and enqueues them.', 'sch>db:claim due (SKIP LOCKED)|sch>q:run #77'], ['A worker runs the job with an idempotency key and records the result.', 'q>w|w>target:POST (run id)|w>db:SUCCEEDED']]},
    points:[['Finding due jobs', '<p>Use an index on (partition, next_run_at). Each check fetches <code>WHERE next_run_at &lt;= now() LIMIT 1000</code>. A timing wheel in memory can hold the next few minutes, to be more exact.</p>'], ['Once, almost always', '<p>Claim with <code>UPDATE … SET lease_until = now()+60s WHERE id=? AND (lease_until IS NULL OR lease_until &lt; now())</code>. Workers pass a run id to the targets as an idempotency key.</p>'], ['The midnight rush', '<p>50,000 jobs at 00:00: spread them with an optional random delay, and size the queue and the workers for bursts.</p>'], ['Failure', '<p>If a scheduler dies, its partitions are given to others when its leases expire. Jobs fire a few seconds late, not never.</p>'], ['Time zones', '<p>Store the cron text and the time zone. Work out next_run_at in UTC, and take care with daylight saving time.</p>']],
    tradeoffs:[['A database with leases', 'Durable and easy to reason about', 'Polling load, and precision of only seconds'], ['At least once, with targets safe to repeat', 'Robust to crashes', 'Targets must handle duplicates']]},
  refs:['l:distributed-locks', 'l:workflow-orchestration', 'l:delivery-semantics']});
C({id:'coupons', level:'intermediate', icon:'🎟️', minutes:35, title:'Promo codes with limited redemptions', tagline:'“First 10,000 orders get ₹200 off”: exactly 10,000.', tags:['atomic counters', 'idempotency', 'contention'],
  prompt:'Marketing creates promo codes such as DIWALI200, with rules: a minimum order, one use for each user, and only the first N uses. During a sale, thousands of users apply the same code every second. Design the redemption so the limits are never exceeded.',
  constraints:['Up to 5,000 redemption attempts a second on one code', 'A hard global cap (for example 10,000) and one use for each user', 'A redemption must be released if the order is cancelled or the payment fails', 'Checkout must stay fast'],
  hints:['What breaks if you check “used &lt; 10,000” and then add one?', 'Where can you make the check and the increase one atomic step, and how do you enforce one use for each user?', 'Reserve at checkout with an atomic script (Redis Lua or a conditional SQL update) that checks the cap and a set of users, with a TTL. Confirm when payment succeeds, and release on failure or expiry. Save redemptions in the database, safe to repeat for an order id.'],
  solution:{summary:'Treat a promo code like scarce stock. Reserve a redemption atomically at checkout, with the cap check and the user check in one step. Confirm it when the order is paid, and release reservations that expire or fail.',
    diagram:{n:[['u', 'client', 'Shopper', '', 0, 1], ['api', 'service', 'Checkout', '', 1, 1], ['gate', 'cache', 'Promo gate', 'Lua: cap + per-user', 2, 0], ['db', 'db', 'Redemptions DB', 'unique (code, user)', 2, 2], ['pay', 'service', 'Payments', '', 3, 1], ['sweep', 'service', 'Expiry sweeper', '', 3, 0]], e:'u>api api>gate api>db api>pay sweep>gate', f:[['Applying the code reserves one redemption atomically.', 'u>api:apply DIWALI200|api>gate:reserve (cap, user)'], ['Payment succeeds. The redemption is confirmed in the database, and it is safe to repeat for an order id.', 'api>pay|api>db:INSERT redemption'], ['Unpaid reservations expire and are returned.', 'sweep>gate:release expired']]},
    points:[['An atomic reservation', '<p>One Lua script does this. If the user is in the set, reject. If used is at the cap, reject.</p><p>Otherwise add 1 to used, add the user to the set, and store the reservation with a TTL.</p>'], ['Durability', '<p>The database row, with a unique (code, user_id) rule, is the source of truth. The gate is rebuilt from it if it is lost.</p>'], ['Contention', '<p>One hot key is fine for Redis (over 100,000 operations a second). A relational row lock would allow only a few thousand a second.</p>'], ['Abuse', '<p>One use for each user is weak against fake accounts. Also limit by device, phone number and payment method.</p>']],
    tradeoffs:[['Reserve, then confirm', 'No over-redemption, and failures release the code', 'A code can look “used up” for a short time while reservations expire'], ['A gate in memory', 'Fast under contention', 'It must be reconciled with the database']]},
  refs:['l:locking', 'l:idempotency-rate-limit-headers', 'case:amazon']});
C({id:'nearby-friends', level:'intermediate', icon:'📍', minutes:40, title:'Nearby friends', tagline:'Who among my friends is within 2 km, updated every 30 seconds?', tags:['geospatial', 'pub/sub', 'presence', 'privacy'],
  prompt:'An opt-in feature shows which friends are within 2 km, with the distances updated as people move. For example, Rahul sees “Priya is 1.2 km away”. Each user has up to 500 friends. 20M users have the feature turned on, and 2M of them are active at once.',
  constraints:['Location updates every 30 s from active users', 'Only friends who opted in, and locations older than 10 minutes are hidden', 'Updates should show within a few seconds', 'Battery and privacy matter'],
  hints:['Is this a “search everyone near me” problem, or only a search among my friends?', 'When my location changes, who needs to hear about it?', 'Keep each active user’s latest location in a cache with a TTL. Publish updates to a channel for each user, and let active friends subscribe to it through their WebSocket server. Each receiver works out the distance and filters by 2 km.'],
  solution:{summary:'The candidates are only a user’s friends, so there is no need for a global geo index. Publish each user’s location to their own channel. Online friends who subscribe to it work out the distance themselves, or their WebSocket server does.',
    diagram:{n:[['a', 'client', 'Priya', 'moves', 0, 0], ['b', 'client', 'Rahul', 'friend', 0, 2], ['ws', 'service', 'WebSocket servers', '', 1, 1], ['loc', 'cache', 'Locations', 'TTL 10 min', 2, 0], ['ps', 'queue', 'Pub/sub', 'channel per user', 2, 2], ['graph', 'db', 'Friends DB', '', 3, 1]], e:'a>ws b>ws ws>loc ws>ps ws>graph', f:[['Priya’s app sends a location. It is cached and published to her channel.', 'a>ws:lat,lng|ws>loc:SET EX 600|ws>ps:publish loc:priya'], ['Rahul’s server is subscribed to his opted-in friends’ channels and forwards nearby ones.', 'ps>ws:Priya update|ws>b:Priya 1.2 km']]},
    points:[['Estimate', '<p>2M active users ÷ 30 s ≈ 67,000 updates a second. Each one goes to the online friends, say 20 on average, which is about 1.3M messages a second inside the pub/sub layer.</p>'], ['Subscriptions', '<p>When a user connects, load their friend list and subscribe to the friends who are online and opted in. Unsubscribe when they disconnect.</p>'], ['Distance', '<p>The receiver works out the distance (the haversine formula). Pass an update on to the client only when the friend is within 2 km, or has just crossed the border.</p>'], ['Privacy', '<p>Make locations less exact, never store a history, and honour an opt-out at once by deleting the cache entry.</p>']],
    tradeoffs:[['A channel for each user', 'The work grows with the number of friends, not with everyone nearby', 'A large pub/sub fan-out'], ['A global geo index', 'Needed to find “people nearby” (strangers)', 'Not needed when it is friends only']]},
  refs:['l:geospatial', 'l:presence', 'l:websockets-at-scale']});
C({id:'metrics', level:'intermediate', icon:'📈', minutes:45, title:'Metrics ingestion and dashboards', tagline:'Ten million data points per second, queried by humans in milliseconds.', tags:['time series', 'downsampling', 'cardinality'],
  prompt:'Design a metrics system. Services send counters and gauges with labels every 10 seconds. Engineers build dashboards and alerts over the last hour, the last day and the last year. For example, a graph shows the 99th percentile delay of the checkout service for the last 30 days.',
  constraints:['10M samples a second, and 50M active time series', 'Dashboards over 1 hour in under 1 s, and over 1 year in under 5 s', 'Alerts checked every 30 s', 'Raw data kept for 15 days, and summaries for 2 years'],
  hints:['Why does time-series data compress so well, and how should you lay it out on disk?', 'A year of 10-second points is billions of points. What should you work out ahead of time?', 'Split by series id. Append to chunks in memory with delta-of-delta and XOR compression, then flush to blocks that never change. Roll data up into 5-minute and 1-hour summaries, and guard against a flood of label values.'],
  solution:{summary:'Take in samples through a stateless tier into shards keyed by series. Store compressed, time-ordered chunks, and build rollups for long ranges. A query fans out to the shards and merges the answers.',
    diagram:{n:[['svc', 'client', 'Services', 'emit metrics', 0, 1], ['ing', 'service', 'Ingesters', 'hash by series', 1, 1], ['wal', 'db', 'Hot blocks', 'compressed chunks', 2, 0], ['obj', 'db', 'Object storage', 'old blocks', 3, 0], ['roll', 'service', 'Downsampler', '5 min · 1 h', 3, 1], ['q', 'service', 'Query engine', 'fan-out + merge', 2, 2], ['ui', 'client', 'Dashboards', '', 4, 2]], e:'svc>ing ing>wal wal>obj obj>roll roll>obj~0.3 ui>q q>wal q>obj', f:[['Samples are routed by series id to an ingester, appended to compressed in-memory chunks, then flushed.', 'svc>ing:http_requests{svc,code}|ing>wal|wal>obj:2 h blocks'], ['A dashboard query fans out to recent blocks and rollups and merges results.', 'ui>q:rate(…[5m]) 30d|q>obj:1 h rollups|q>wal:last 2 h']]},
    points:[['Compression', '<p>Timestamps are stored as delta-of-delta and values as XOR (the Gorilla method). That is about 1.4 bytes for each sample instead of 16.</p>'], ['Estimate', '<p>10M samples a second × 1.4 B ≈ 14 MB a second ≈ 1.2 TB a day of raw data. 15 days is about 18 TB. Rollups are 30 to 360 times smaller.</p>'], ['Cardinality', '<p>A label such as user_id creates millions of series. Set limits for each metric, and reject or drop labels that go over.</p>'], ['Alerts', '<p>A rule evaluator queries recent data every 30 s. Use burn-rate alerts on an SLO (a goal for reliability), not raw thresholds.</p>']],
    tradeoffs:[['Rollups', 'Fast queries over long ranges', 'Detail is lost, so keep raw data only for recent days'], ['Pull or push collection', 'Pull notices dead targets', 'Push suits short-lived jobs']]},
  refs:['l:time-series', 'l:golden-signals-red-use', 'l:alerting-oncall']});
C({id:'email-campaigns', level:'intermediate', icon:'📧', minutes:40, title:'Sending 100 million marketing emails', tagline:'Fast, polite to inbox providers, and never twice.', tags:['queues', 'throttling', 'idempotency', 'webhooks'],
  prompt:'A retailer sends a festive campaign to 100M subscribers. It must finish within 4 hours, respect each email provider’s rate limits, and personalise every message. It must also handle bounces and unsubscribes, and never send a duplicate. How would you build it?',
  constraints:['100M recipients in 4 hours is about 7,000 emails a second', 'Gmail, Outlook and others slow down senders that go too fast', 'An unsubscribe must apply at once, even in the middle of a campaign', 'Workers crash, and the campaign must resume without duplicates'],
  hints:['Can one process loop over 100M rows? How would you split the work so it can resume?', 'Different receiving providers need different rates. How do you shape the traffic for each domain?', 'Split the recipients into batches recorded in a table and run them through a queue. Keep a sent-log keyed by (campaign, recipient) so a repeat is safe. Check the suppression list at send time, and use a token bucket for each domain.'],
  solution:{summary:'Turn the campaign into many small batches that can resume. Workers render and send with a rate limit for each provider, check the suppression list at send time, and record each send so it is safe to repeat. Bounces and complaints come back as events.',
    diagram:{n:[['mkt', 'client', 'Marketer', '', 0, 1], ['plan', 'service', 'Campaign planner', 'creates batches', 1, 1], ['q', 'queue', 'Batch queue', '', 2, 1], ['w', 'service', 'Send workers', 'per-domain buckets', 3, 1], ['sup', 'cache', 'Suppression list', 'unsubscribes', 3, 0], ['log', 'db', 'Sent log', 'unique (campaign, user)', 3, 2], ['mta', 'ext', 'Email providers', '', 4, 1]], e:'mkt>plan plan>q q>w w>sup w>log w>mta mta>log~0.3', f:[['The planner splits the recipients into 100,000 batches of 1,000.', 'mkt>plan:launch|plan>q:batches'], ['A worker checks suppression, renders, sends within the domain’s rate, and records the send.', 'q>w|w>sup:skip unsubscribed|w>mta:SMTP|w>log:sent'], ['Bounces and complaints update the logs and suppression list.', 'mta>log:bounce webhook']]},
    points:[['Safe to repeat', '<p>Before sending, insert (campaign_id, recipient_id) into the sent log. A duplicate key means skip. A batch that resumes after a crash then cannot send twice.</p>'], ['Throttling', '<p>Use a token bucket for each receiving domain and each sending IP address. Slow down when the provider replies with a 4xx deferral.</p>'], ['Freshness', '<p>Check the suppression list at send time, not when the batches were made.</p>'], ['Deliverability', '<p>SPF, DKIM and DMARC, warmed-up IP addresses and a clean list matter as much as speed.</p>']],
    tradeoffs:[['Batches in a queue', 'Parallel and able to resume', 'The order across batches is not guaranteed'], ['A sent-log check for each email', 'No duplicates', 'One extra write for each email']]},
  refs:['l:backpressure', 'l:idempotency-rate-limit-headers', 'case:notification-service']});
C({id:'price-alerts', level:'intermediate', icon:'📉', minutes:40, title:'Stock price alerts', tagline:'Notify 5 million users when a price crosses their threshold.', tags:['streams', 'indexing', 'fan-out'],
  prompt:'Users set alerts such as “tell me when INFY drops below ₹1,400”. The prices of 5,000 stocks change several times a second during market hours. Design the alerting system.',
  constraints:['20M active alerts on 5,000 symbols', '50,000 price ticks a second', 'Notify within 2 s of the crossing', 'Each alert fires once, and then the user turns it on again'],
  hints:['For each tick, could you check all 20M alerts? What smaller set needs checking?', 'For one symbol, alerts are thresholds. How would you find every threshold crossed between the old price and the new one?', 'Split the alerts by symbol. For each symbol, keep a sorted list of thresholds (above and below). On each tick, look up the thresholds between the old and new price, fire them, and remove them in one atomic step. Send the notifications through a queue.'],
  solution:{summary:'Split by symbol and keep the thresholds in sorted order, so each tick touches only the alerts in the price range it just crossed.',
    diagram:{n:[['feed', 'ext', 'Exchange feed', 'ticks', 0, 1, 120], ['part', 'queue', 'Ticks by symbol', 'partitioned', 1, 1], ['eval', 'service', 'Evaluators', 'sorted thresholds', 2, 1], ['adb', 'db', 'Alerts DB', '', 2, 2], ['nq', 'queue', 'Notify queue', '', 3, 1], ['push', 'ext', 'Push / SMS', '', 4, 1], ['u', 'client', 'User', 'creates alert', 1, 2]], e:'feed>part part>eval eval>adb eval>nq nq>push u>adb', f:[['A tick for INFY reaches the evaluator that owns INFY.', 'feed>part:INFY 1,398|part>eval'], ['It range-queries thresholds between the previous and new price, marks them fired, and queues notifications.', 'eval>adb:fired 1,212 alerts|eval>nq|nq>push']]},
    points:[['Index', '<p>For each symbol, keep two sorted sets: thresholds for “below” and for “above”. A drop from 1,412 to 1,398 fires every “below” alert with a threshold in [1,398, 1,412).</p>'], ['Estimate', '<p>Most ticks cross no threshold. The work depends on how many alerts fire, not on how many are stored.</p>'], ['Exactly once', '<p>Remove the alert from the index and mark it as fired in one transaction before notifying. The notifications are safe to repeat for an alert id.</p>'], ['Hot symbols', '<p>A crash in a popular stock fires millions of alerts at once. The notification queue absorbs the burst.</p>']],
    tradeoffs:[['Split by symbol', 'Ticks stay in order for each symbol, and indexes are local', 'Hot symbols concentrate the load'], ['Indexes in memory', 'Range lookups take microseconds', 'They must be rebuilt from the database on restart']]},
  refs:['l:batch-vs-stream', 'l:kafka', 'l:fan-out']});
C({id:'trending', level:'intermediate', icon:'🔥', minutes:40, title:'Top-K trending hashtags', tagline:'What is trending in the last hour, updated every minute?', tags:['streaming', 'count-min sketch', 'sliding windows', 'top-k'],
  prompt:'Show the top 10 trending hashtags over the last hour, for the world and for each city, refreshed every minute. The input is a stream of 500,000 posts a second. For example, when a match ends in Mumbai, #IPLFinal should climb to the top of Mumbai’s list within a minute or two.',
  constraints:['500,000 posts a second, with about 2 hashtags each', 'Millions of different hashtags', 'A top 10 for each of 2,000 cities', 'Counts can be approximate, and the list should be fresh within a minute'],
  hints:['Can you keep an exact counter for every hashtag in every city and every time window?', 'Which structure counts how often things appear in a fixed amount of memory, and how do you get the top K from it?', 'Use minute buckets, each with a count-min sketch and a min-heap of candidates for each region. Merge the last 60 buckets for the hour. Split the stream by hashtag (or by region), and combine the partial top-K lists.'],
  solution:{summary:'Count in fixed memory with a count-min sketch for each minute bucket, and keep a small heap of the most frequent tags. Slide a 60-minute window by merging buckets. Split the work and merge the partial top-K lists.',
    diagram:{n:[['posts', 'client', 'Posts stream', '', 0, 1], ['k', 'queue', 'Kafka', 'by hashtag', 1, 1], ['agg', 'service', 'Stream counters', 'CMS + heap / minute', 2, 1], ['merge', 'service', 'Top-K merger', 'last 60 min', 3, 1], ['cache', 'cache', 'Trending cache', 'global + city', 4, 1], ['app', 'client', 'App', '', 4, 2]], e:'posts>k k>agg agg>merge merge>cache app>cache', f:[['Hashtags are partitioned and counted per minute in sketches with candidate heaps.', 'posts>k:#IPLFinal|k>agg'], ['Every minute, partial top-Ks for the last hour are merged and published.', 'agg>merge:partial top-K|merge>cache:top 10'], ['Apps read the cached lists.', 'app>cache']]},
    points:[['Count-min sketch', '<p>It is a grid of counters, with a width and a depth. An estimate is never too low. The error is about the total count divided by the width, and the depth sets how likely that error is.</p>'], ['Trending, not just popular', '<p>Rank by growth: the current hour against a baseline for the same hour (a z-score). Otherwise #IPL is always on top.</p>'], ['Splitting the work', '<p>Split by hashtag to get counts that are almost exact. The lists for each city come from events that carry a region tag.</p>'], ['Abuse', '<p>Filter out bot accounts and organised spam before counting.</p>']],
    tradeoffs:[['Sketches', 'Fixed memory, however many different tags there are', 'The counts are approximate'], ['Minute buckets', 'A simple sliding window', 'Only 1-minute detail']]},
  refs:['l:hll-cms', 'l:batch-vs-stream', 'pg:bloom']});
C({id:'edtech-video', level:'intermediate', icon:'🎓', minutes:40, title:'Video pipeline for an ed-tech platform', tagline:'Teachers upload lectures, and students stream them on 3G.', tags:['transcoding', 'workflows', 'abr', 'drm'],
  prompt:'Teachers upload lecture recordings of 1 to 3 hours. Each one must become an adaptive stream (360p to 1080p), with automatic captions, a thumbnail and chapter markers. Only enrolled students may play it. For example, Sana’s 3-hour physics lecture should be ready for her class within the hour.',
  constraints:['5,000 hours uploaded a day', 'Students are mostly on mobile data in small towns', 'Paid content: stop casual downloading and link sharing', 'Processing finishes within 1 hour of the upload'],
  hints:['A 3-hour file is huge. How do you make transcoding fast, and able to resume after a failure?', 'Several steps can run at the same time. How would you coordinate them and retry failures?', 'Upload in chunks that can resume, then split into segments and transcode them in parallel into a bitrate ladder. Package as HLS with encryption keys, and make captions with speech-to-text at the same time. A workflow engine tracks the steps. A CDN with signed URLs and a key server checks enrolment.'],
  solution:{summary:'Treat the processing as a workflow of steps that are each safe to repeat. Split, transcode the segments in parallel and package with encryption, while captions and thumbnails run alongside. Deliver through a CDN with short-lived signed URLs and keys that depend on enrolment.',
    diagram:{n:[['t', 'client', 'Teacher', 'upload', 0, 0], ['s', 'client', 'Student', '', 0, 2], ['up', 'service', 'Upload service', 'resumable', 1, 0], ['wf', 'service', 'Workflow engine', 'DAG + retries', 2, 1], ['tx', 'service', 'Transcoders', 'segments ×N', 3, 0], ['cap', 'service', 'Captions', 'speech-to-text', 3, 2], ['st', 'db', 'Storage', 'HLS + keys', 4, 1], ['cdn', 'cdn', 'CDN', 'signed URLs', 1, 2]], e:'t>up up>wf wf>tx wf>cap tx>st cap>st s>cdn cdn>st~0.1', f:[['The upload completes and starts a workflow.', 't>up:chunked upload|up>wf:new lecture'], ['Segments transcode in parallel while captions run alongside.', 'wf>tx:split + ladder|wf>cap|tx>st:HLS (AES)|cap>st:VTT'], ['An enrolled student gets signed URLs and streams adaptively.', 's>cdn:playlist + segments|cdn>st']]},
    points:[['Estimate', '<p>5,000 hours a day × 4 renditions. With parallel encoding of the segments, a 3-hour lecture finishes in minutes on a pool of a few hundred cores.</p>'], ['Bitrates', '<p>Lectures are mostly still slides, so low bitrates (150 to 800 kbps) look fine. Add an audio-only version for very weak networks.</p>'], ['Protection', '<p>Use HLS with AES-128 or DRM. Check enrolment on every key request, sign the URLs and keep them short-lived. Put the user id on the video as a watermark, to discourage leaks.</p>'], ['Workflow', '<p>Make each task safe to repeat and retry it. The engine records the state, so a crashed run resumes instead of starting again.</p>']],
    tradeoffs:[['Parallel transcoding of segments', 'Fast turnaround', 'More orchestration'], ['DRM or AES with signed URLs', 'DRM is stronger', 'DRM costs more and not every device supports it']]},
  refs:['l:transcoding-pipeline', 'l:live-streaming-abr', 'l:workflow-orchestration', 'case:youtube']});
C({id:'api-gateway', level:'intermediate', icon:'🚪', minutes:40, title:'API gateway with auth and quotas', tagline:'One front door for 200 services and 10,000 partner apps.', tags:['gateway', 'auth', 'rate limiting', 'routing'],
  prompt:'A company offers public APIs to 10,000 partner apps. Design a gateway that checks API keys and OAuth tokens and applies a quota for each plan. It sends each request to one of 200 internal services and records usage for billing. For example, a partner on the “Basic” plan gets 600 calls a minute.',
  constraints:['200,000 requests a second at peak', 'The gateway adds under 5 ms for 99 of 100 requests', 'Quotas for each partner for each minute and each month', 'Usage must be billable: no call lost and none counted twice'],
  hints:['Which checks can the gateway node do on its own, and which need shared state?', 'A per-minute quota across 50 gateway nodes: how do you count without a network call on every request?', 'Check JWTs locally with cached keys, and look up API keys in a local cache. Enforce quotas with local token buckets that sync to Redis in small batches. Route with a service registry, and send usage events to a log so billing can add them up.'],
  solution:{summary:'Keep the hot path local: cached credentials, local token buckets that are reconciled with a shared store now and then, and a routing table from service discovery. Usage goes to an event log in the background, for exact billing.',
    diagram:{n:[['p', 'client', 'Partner app', '', 0, 1], ['gw', 'lb', 'Gateway nodes', 'auth · quotas · routing', 1, 1], ['redis', 'cache', 'Quota store', 'Redis', 2, 0], ['reg', 'service', 'Service registry', '', 2, 2], ['svc', 'service', 'Internal services', '×200', 3, 1], ['log', 'queue', 'Usage log', 'Kafka', 3, 0], ['bill', 'service', 'Billing', 'aggregates', 4, 0]], e:'p>gw gw>redis gw>reg gw>svc gw>log log>bill', f:[['The gateway authenticates locally and checks its local token bucket.', 'p>gw:GET /v2/orders (key)|gw>redis:sync usage every 100 ms'], ['It routes to a healthy instance and emits a usage event.', 'gw>reg:orders → instances|gw>svc|gw>log:usage event'], ['Billing aggregates usage per partner per month.', 'log>bill']]},
    points:[['Delay budget', '<p>Most requests need no remote call. Checking a JWT and looking up a cached key take microseconds.</p>'], ['Quotas across nodes', '<p>Each node takes a share of the quota, or syncs its counts about every 100 ms. Allow a small overshoot, or use one central Redis bucket for strict limits per second.</p>'], ['Billing accuracy', '<p>Usage events carry a request id, and the aggregator removes duplicates. Monthly quotas read from the aggregated counts.</p>'], ['Resilience', '<p>If Redis is down, fall back to limits kept on each node. Never let the quota store take the API down.</p>']],
    tradeoffs:[['Local quotas that are approximate', 'A very small delay', 'A short overshoot across nodes'], ['Usage logging in the background', 'Off the hot path', 'Billing lags by minutes']]},
  refs:['l:proxies-gateway-bff', 'l:rate-limiting', 'l:api-keys-mtls', 'case:rate-limiter']});
C({id:'whiteboard', level:'intermediate', icon:'🖍️', minutes:45, title:'Collaborative whiteboard', tagline:'Twenty people drawing on one canvas, offline edits included.', tags:['crdt', 'websockets', 'sync', 'snapshots'],
  prompt:'Design a shared whiteboard with sticky notes, shapes, arrows and freehand drawing. Up to 50 people edit one board at once, see each other’s cursors, and can keep working for a short time offline. For example, Ravi and Meera both drag the same sticky note at the same moment.',
  constraints:['50 editors at once on a board, and 100,000 active boards', 'Changes show to others in under 200 ms', 'Offline edits merge when the user reconnects', 'A board with 10,000 objects must open quickly'],
  hints:['Two people move the same sticky note at once. What should happen?', 'Do you need operational transformation for every character here, or something simpler for each object?', 'Model the board as a map of objects, with a last-writer-wins value for each property (a CRDT-style register). Sync operations over WebSocket through one session for each board. Save an operation log plus snapshots, and send cursors as short-lived presence.'],
  solution:{summary:'Objects are independent, so conflicts happen for each property. Use last-writer-wins values with logical timestamps (a simple CRDT), relay the operations through a session server for each board, and save snapshots plus recent operations.',
    diagram:{n:[['a', 'client', 'Editor A', '', 0, 0], ['b', 'client', 'Editor B', '', 0, 2], ['gw', 'service', 'WebSocket gateway', '', 1, 1], ['sess', 'service', 'Board session', 'one owner per board', 2, 1], ['log', 'db', 'Op log', '', 3, 0], ['snap', 'db', 'Snapshots', '', 3, 2]], e:'a>gw b>gw gw>sess sess>log sess>snap', f:[['A moves a note. The op carries a logical timestamp and goes to the board’s session.', 'a>gw:note 17 x=420 @(lamport 812, A)|gw>sess'], ['The session saves and broadcasts it. Each client merges with last-writer-wins for each property.', 'sess>log|sess>gw|gw>b'], ['Snapshots let large boards open fast.', 'sess>snap:every 1,000 ops']]},
    points:[['Conflicts', '<p>For each property of an object, the highest (Lamport time, client id) wins. A delete beats a move, using a tombstone.</p>'], ['Freehand', '<p>A stroke is an object that is only added to. It is made once and rarely edited, so it has no conflicts.</p>'], ['Offline', '<p>Queue the operations on the device with timestamps. On reconnect, send them and merge. Last-writer-wins guarantees that every copy ends the same.</p>'], ['Scale', '<p>Send each board to one session server by hash. A large board loads a snapshot, then the recent operations.</p>']],
    tradeoffs:[['Last-writer-wins for each property', 'Simple, and it always converges', 'When two people edit the same property, one edit is lost'], ['A session for each board', 'Order and fan-out in one place', 'A very busy board is limited by one server']]},
  refs:['l:crdts-merkle', 'l:offline-first-sync', 'case:google-docs', 'pg:vector-clock']});
})();
